import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentApp() {
  const [unitId, setUnitId] = useState(1);
  const [questionsByTopic, setQuestionsByTopic] = useState({});
  const student_id = 1; // example
  const class_name = "APChem";
  const subject = "Chemistry";

  useEffect(() => {
    fetchQuestions(unitId);
  }, [unitId]);

  const fetchQuestions = async (id) => {
  const BASE_URL = process.env.REACT_APP_FLASK_URL || "http://localhost:5000";

const res = await axios.get(`${BASE_URL}/teacher_dashboard`);


    setQuestionsByTopic(res.data);
  };

  const sendResponse = async (topic, level) => {
    await axios.post('http://localhost:5000/log_response', {
      student_id,
      class: class_name,
      subject,
      unit_id: unitId,
      topic,
      understanding_level: level
    });
    alert(`Recorded ${level} for ${topic}`);
  };

  return (
    <div>
      <h2>Student App</h2>
      <label>Unit ID: </label>
      <input type="number" value={unitId} onChange={e=>setUnitId(e.target.value)} />
      <hr />
      {Object.keys(questionsByTopic).map(topic => (
        <div key={topic} style={{marginBottom:"20px"}}>
          <h3>{topic}</h3>
          <ul>
            {questionsByTopic[topic].map((q,i)=><li key={i}>{q}</li>)}
          </ul>
          <button onClick={()=>sendResponse(topic,"green")}>Green</button>
          <button onClick={()=>sendResponse(topic,"yellow")}>Yellow</button>
          <button onClick={()=>sendResponse(topic,"red")}>Red</button>
        </div>
      ))}
    </div>
  )
}
